  ('arabic-course-for-non-native-speakers-2024', 'الجمعية تنظّم دورة تدريبية في تعليم اللغة العربية لغير الناطقين بها', 'Association runs a training course teaching Arabic to non-native speakers', 'شارك عدد من طلاب المنح في دورة مكثفة لتعليم اللغة العربية استعداداً للفصل الدراسي الجديد.', 'A group of scholarship students took part in an intensive Arabic course ahead of the new term.', NULL, NULL, (SELECT id FROM news_categories WHERE slug = 'training'), (SELECT id FROM media_assets WHERE checksum_sha256 = '234a8bf31068ebc9d684d74f0d826cbcebcb897f030b342c2e96c8bcafed4e60'), '2024-02-10', 0, 0, 1, NULL),
  ('new-student-orientation-2024', 'لقاء توجيهي جديد لطلاب المنح الوافدين', 'New orientation session for incoming scholarship students', 'استقبلت الجمعية دفعة جديدة من طلاب المنح الوافدين في لقاء تعريفي بالخدمات والبرامج المتاحة.', 'The association welcomed a new group of incoming scholarship students in an orientation session on its services and programmes.', NULL, NULL, (SELECT id FROM news_categories WHERE slug = 'student-care'), (SELECT id FROM media_assets WHERE checksum_sha256 = '19fdb23d02724510568e8c14564485427bddf198c4f77c562ba77672478f7dc1'), '2024-09-01', 0, 0, 1, NULL);
