  ('سالم الحربي', NULL, 'salem.harbi@example.com', 'feedback', 'أقترح زيادة الموارد التعليمية المنشورة على الموقع، خصوصاً في مجال تعليم اللغة العربية.', 'archived', 'ar', NULL, NULL),
  ('فاطمة الزهراني', '+966 50 987 6543', 'fatima.zahrani@example.com', 'scholarship', 'هل يمكن التقديم على المنحة لمرحلة الدكتوراه، وما المستندات الإضافية المطلوبة لهذه المرحلة؟', 'read', 'ar', NULL, NULL),
